function rotateRight(head, k) {
  if (head === null || head.next === null) return head;
  let n = 0;
  for (let curr = head; curr !== null; curr = curr.next) n++;
  for (let r = 0; r < k % n; r++) {          // rotate by one, k mod n times
    let beforeTail = head;
    while (beforeTail.next.next !== null) beforeTail = beforeTail.next;
    const tail = beforeTail.next;
    beforeTail.next = null;                  // detach the last node...
    tail.next = head;                        // ...and put it in front
    head = tail;
  }
  return head;
}

